  ('kaisaschmoan', 'Kaisaschmoan', '', '', '', '', 'Kaiserschmarren', '[{"kategorie": "wörtlich", "text": "\"der feinste Schmarren von allen\" (vorangestellt drückt der Wortbestandteil \"Kaiser-\" bei zusammengesetzten Hautpwörtern stets aus, dass etwas besonders gut und fein ist)"}, {"kategorie": "Gastronomie", "text": "\"Schmarren aus gerissenem Omlette-Teig\" (beliebtes Dessert der Altwiener Küche, angeblich die Lieblingsspeise von Kaiser Franz Josef I.)"}, {"kategorie": "", "text": "[[Mehlspeise]] aus einem Teig mit viel Eiern, Milch, Mehl, Salz und Zucker, der beim Braten in kleine Stücke zerrupft wird)"}]'::jsonb, ''),
