  ('scheissomaat', 'Scheissomaat', '', '', '', '', 'Scheißomat', '[{"kategorie": "wörtlich", "text": "\"Scheißautomat\" (Wortkontraktion aus [[scheißen]]=\"kacken\" und \"Automat\")"}, {"kategorie": "scherzhaft für", "text": "Hintern, Gesäß, [[Oasch]], [[Toches]], [[Schorschi]]"}, {"kategorie": "", "text": "Toilette, Klo, WC, [[Heisl]]"}]'::jsonb, ''),
  ('gamaaschnritta', 'Gamaaschnritta', '', '', '', '', 'Gamaschenritter', '[{"kategorie": "scherzhaft für", "text": "\"Infanterist\" (\"Fußsoldat, der Gamaschen trägt\"; Determinativkompositum aus \"Gamasche\"=\"Beinschutz\" und \"Ritter\"=\"Krieger\")"}, {"kategorie": "fig.", "text": "Lebemann, Galan, Gesellschaftsritter, Dandy, Salonheld, [[Gigerl]]"}]'::jsonb, ''),
  ('gaumsuawal', 'Gaumsuawal', '', '', '', '', 'Gamsurberl', '[{"kategorie": "wörtlich", "text": "\"sagenumwobener Wildschütz\" (Determinativkompositum aus \"Gams\"=\"Gemse\" und \"Urberl\"=\"Urban, der Wildschütz vom Grimming\")"}, {"kategorie": "fig.", "text": "Draufgänger, wilder Hund, Teufelskerl, Haudegen, [[Nixscheißer]]"}]'::jsonb, ''),
