  ('naagal', 'Naagal', '', '', '', '', 'Nagerl', '[{"kategorie": "wörtlich", "text": "\"Näglein\" (Verkleinerungsform von \"Nagel\", vom mittelhochdeutschen \"nagel\"=\"Nagel\" bzw. botanisch auch \"Gewürznelke\")"}, {"kategorie": "techn.", "text": "Metallstiftchen, Reißnägelchen"}, {"kategorie": "allg.", "text": "Fingernägelchen, Zehennägelchen"}, {"kategorie": "bot.", "text": "Nelke, Gewürznelke, Nelkenstängelchen (vom mittelhochdeutschen \"nagel\"=\"Nelke\", heute noch erhalten in der Textzeile des Wiegenlieds von Johannes Brahms \"Guten Abend, gut Nacht\", nämlich: \"mit Rosen bedacht, mit Näglein besteckt, schlupf unter die Deck\")"}]'::jsonb, ''),
  ('gfrea', 'Gfrea', '', '', '', '', 'Gefrör', '[{"kategorie": "wörtlich", "text": "\"gefrierende Kälte\" (vom mittelhochdeutschen \"gevrœren\"=\"machen, dass etwas gefriert\")"}, {"kategorie": "allg.", "text": "Eiseskälte, strenger Frost, gefrierende Temperaturen"}, {"kategorie": "med.", "text": "Frostbeule, Frostgeschwulst, Kälteödem"}, {"kategorie": "", "text": "Frostschaden (an Obst, Gemüse, etc.), Frostbrand, Gefrierschaden"}]'::jsonb, 'si a Gfrea auf da Noosn hoin'),
